          {evento.status === "publicado" && (
            <button
              type="button"
              disabled={confirmados < 2}
              title={confirmados < 2 ? "É preciso ter pelo menos 2 times confirmados." : undefined}
              onClick={async () => {
                if (!window.confirm("Sortear a chave? As inscrições serão fechadas.")) return;
