/**
 * Gestão de um evento pelo admin: publicar, cancelar, inscrições, sorteio e
 * resultados da chave.
 *
 * Spec: SPEC/2026-11-27-eventos-e-torneios.md
 */

"use client";

import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";
import { ChaveTorneio } from "@/components/eventos/ChaveTorneio";
import type { EntradaResultado, Evento, InscricaoEvento, PartidaEvento } from "@/lib/eventos/types";
import type { useEventosAdmin } from "@/hooks/useEventosService";

type AcoesAdmin = ReturnType<typeof useEventosAdmin>;

const ROTULO_STATUS: Record<Evento["status"], string> = {
  rascunho: "Rascunho",
  publicado: "Publicado",
  chave_sorteada: "Chave sorteada",
  encerrado: "Encerrado",
  cancelado: "Cancelado",
};

export function GestaoEvento({ evento, acoes, onEditar }: { evento: Evento; acoes: AcoesAdmin; onEditar: () => void }) {
  const [inscricoes, setInscricoes] = useState<InscricaoEvento[]>([]);
  const [partidas, setPartidas] = useState<PartidaEvento[]>([]);
  const { listarInscricoes, listarPartidas } = acoes;

  const buscar = useCallback(
    () => Promise.all([listarInscricoes(evento.id), listarPartidas(evento.id)]),
    [evento.id, listarInscricoes, listarPartidas]
  );

  const recarregar = useCallback(async () => {
    const [lista, chave] = await buscar();
    setInscricoes(lista);
    setPartidas(chave);
  }, [buscar]);

  useEffect(() => {
    let ativo = true;
    void buscar().then(([lista, chave]) => {
      if (!ativo) return;
      setInscricoes(lista);
      setPartidas(chave);
    });
    return () => {
      ativo = false;
    };
  }, [buscar]);

  const avisar = (r: { ok: true } | { ok: false; erro: string }, sucesso: string) => {
    if (r.ok) toast.success(sucesso);
    else toast.error("Não foi possível concluir", { description: r.erro });
    return r.ok;
  };

  const confirmados = inscricoes.filter((i) => i.confirmada).length;
  const nomes = Object.fromEntries(inscricoes.map((i) => [i.id, i.nomeTime]));

  const lancar = async (partidaId: string, entrada: EntradaResultado | "desfazer") => {
    const r = await acoes.alterarResultado(evento, partidas, partidaId, entrada);
    if (r.ok) setPartidas(r.partidas);
    else toast.error("Resultado não salvo", { description: r.erro });
  };

  return (
    <section className="space-y-6 rounded-2xl border border-slate-800 bg-slate-900/40 p-5" aria-label={`Gestão de ${evento.nome}`}>
      <header className="flex flex-wrap items-center gap-2">
        <h3 className="mr-auto text-lg font-bold text-white">{evento.nome}</h3>
        <span className="rounded-full bg-slate-800 px-3 py-1 text-xs text-slate-300">{ROTULO_STATUS[evento.status]}</span>
        {evento.status === "rascunho" && (
          <>
            <button type="button" onClick={onEditar} className="rounded-lg bg-slate-700 px-3 py-1.5 text-sm text-slate-200">Editar</button>
            <button type="button" onClick={async () => avisar(await acoes.publicar(evento), "Evento publicado e quadra bloqueada.")} className="rounded-lg bg-emerald-600 px-3 py-1.5 text-sm font-semibold text-white">
              Publicar
            </button>
          </>
        )}
        {(evento.status === "rascunho" || evento.status === "publicado") && (
          <button
            type="button"
            onClick={async () => {
              if (window.confirm("Cancelar o evento e liberar a quadra?")) avisar(await acoes.cancelar(evento), "Evento cancelado.");
            }}
            className="rounded-lg bg-red-900/60 px-3 py-1.5 text-sm text-red-200"
          >
            Cancelar evento
          </button>
        )}
      </header>

      {evento.tipo === "torneio" && (
        <>
          <div>
            <h4 className="mb-2 text-sm font-semibold text-slate-200">
              Inscrições ({inscricoes.length}{evento.maxTimes ? ` de ${evento.maxTimes}` : ""}) · {confirmados} confirmadas
            </h4>
            {inscricoes.length === 0 ? (
              <p className="text-sm text-slate-400">Nenhuma inscrição ainda.</p>
            ) : (
              <ul className="divide-y divide-slate-800 text-sm">
                {inscricoes.map((i) => (
                  <li key={i.id} className="flex flex-wrap items-center gap-2 py-2">
                    <span className="mr-auto text-white">{i.nomeTime}</span>
                    <span className="text-slate-400">{i.responsavelNome} · {i.responsavelWhatsapp}</span>
                    {evento.status === "publicado" && (
                      <>
                        <button
                          type="button"
                          onClick={async () => {
                            if (avisar(await acoes.confirmarInscricao(i.id, !i.confirmada), i.confirmada ? "Confirmação retirada." : "Inscrição confirmada.")) await recarregar();
                          }}
                          className={`rounded-md px-2 py-1 text-xs ${i.confirmada ? "bg-emerald-700 text-white" : "bg-slate-700 text-slate-200"}`}
                        >
                          {i.confirmada ? `Confirmada: desfazer (${i.nomeTime})` : `Confirmar pagamento (${i.nomeTime})`}
                        </button>
                        <button
                          type="button"
                          onClick={async () => {
                            if (window.confirm(`Remover a inscrição de ${i.nomeTime}?`) && avisar(await acoes.removerInscricao(i.id), "Inscrição removida.")) await recarregar();
                          }}
                          className="rounded-md bg-red-900/60 px-2 py-1 text-xs text-red-200"
                        >
                          Remover
                        </button>
                      </>
                    )}
                  </li>
                ))}
              </ul>
            )}
          </div>

          {evento.status === "publicado" && (
            <button
              type="button"
              disabled={confirmados < 2}
              title={confirmados < 2 ? "É preciso ter pelo menos 2 times confirmados." : undefined}
              onClick={async () => {
                if (!window.confirm("Sortear a chave? As inscrições serão fechadas.")) return;
                if (avisar(await acoes.sortearChave(evento, inscricoes), "Chave sorteada.")) await recarregar();
              }}
              className="rounded-lg bg-amber-600 px-4 py-2 text-sm font-semibold text-white disabled:opacity-40"
            >
              Sortear chave ({confirmados} times)
            </button>
          )}

          {(evento.status === "chave_sorteada" || evento.status === "encerrado") && (
            <ChaveTorneio partidas={partidas} nomes={nomes} onLancar={evento.status === "chave_sorteada" ? lancar : undefined} />
          )}
        </>
      )}
    </section>
  );
}

/**
 * Hooks de eventos e torneios: gestão pelo admin, página pública do evento e
 * seção da landing.
 *
 * Spec: SPEC/2026-11-27-eventos-e-torneios.md
 */

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { getHoje } from "@/lib/constants";
import { campeao, desfazerResultado, embaralhar, gerarChave, registrarResultado } from "@/lib/eventos/chave";
import {
  eventosParaLanding,
  horariosDoEvento,
  situacaoInscricao,
  traduzirErroEvento,
  validarEvento,
  validarNomeTime,
} from "@/lib/eventos/regras";
import type { EntradaResultado, Evento, InscricaoEvento, PartidaEvento } from "@/lib/eventos/types";
import {
  confirmarInscricao,
  inscreverTime,
  listarEventos,
  listarInscricoes,
  listarPartidas,
  listarTimesPublicos,
  removerInscricao,
  salvarEvento,
  salvarPartidas,
  type ResultadoEventos,
} from "@/lib/supabase/eventosRepository";
import { useReservasService } from "@/hooks/useReservasService";
import { useUserAuth } from "@/hooks/useUserAuth";

type Resultado = { ok: true } | { ok: false; erro: string };

const gerarId = (prefixo: string) => `${prefixo}_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;

function comoResultado(r: ResultadoEventos): Resultado {
  return r.ok ? { ok: true } : { ok: false, erro: r.erro };
}

/** Partidas que mudaram, para gravar só o necessário. */
function partidasAlteradas(antes: PartidaEvento[], depois: PartidaEvento[]): PartidaEvento[] {
  return depois.filter((p) => JSON.stringify(p) !== JSON.stringify(antes.find((a) => a.id === p.id)));
}

// ─── Admin ────────────────────────────────────────────────────────────────────

export function useEventosAdmin() {
  const { criarBloqueio, removerBloqueio } = useReservasService();
  const [eventos, setEventos] = useState<Evento[]>([]);
  const [carregando, setCarregando] = useState(true);

  const recarregar = useCallback(async () => {
    setEventos(await listarEventos());
    setCarregando(false);
  }, []);

  useEffect(() => {
    let ativo = true;
    void listarEventos().then((lista) => {
      if (!ativo) return;
      setEventos(lista);
      setCarregando(false);
    });
    return () => {
      ativo = false;
    };
  }, []);

  /** Cria ou edita um evento em rascunho. */
  const salvarRascunho = useCallback(
    async (dados: Omit<Evento, "id" | "status" | "reservasBloqueio"> & { id?: string }): Promise<Resultado> => {
      const erros = validarEvento(dados, getHoje());
      if (erros.length > 0) return { ok: false, erro: erros.join(" ") };
      const evento: Evento = { ...dados, id: dados.id ?? gerarId("evt"), status: "rascunho", reservasBloqueio: [] };
      const r = await salvarEvento(evento);
      if (r.ok) await recarregar();
      return comoResultado(r);
    },
    [recarregar]
  );

  /** Publica o evento, bloqueando a quadra no horário. Se algo falhar, desfaz os bloqueios. */
  const publicar = useCallback(
    async (evento: Evento): Promise<Resultado> => {
      const erros = validarEvento(evento, getHoje());
      if (erros.length > 0) return { ok: false, erro: erros.join(" ") };

      const bloqueios: string[] = [];
      if (evento.quadraId) {
        const bloqueio = await criarBloqueio({
          quadraId: evento.quadraId,
          data: evento.data,
          horarios: horariosDoEvento(evento),
          motivo: `Evento: ${evento.nome}`,
        });
        if (!bloqueio.ok || !bloqueio.reserva) {
          return { ok: false, erro: bloqueio.motivo ?? traduzirErroEvento({ message: "horario_ocupado" }) };
        }
        bloqueios.push(bloqueio.reserva.id);
      }

      const r = await salvarEvento({ ...evento, status: "publicado", reservasBloqueio: bloqueios });
      if (!r.ok) {
        for (const id of bloqueios) await removerBloqueio(id);
        return comoResultado(r);
      }
      await recarregar();
      return { ok: true };
    },
    [criarBloqueio, removerBloqueio, recarregar]
  );

  /** Cancela o evento e libera a quadra. */
  const cancelar = useCallback(
    async (evento: Evento): Promise<Resultado> => {
      const r = await salvarEvento({ ...evento, status: "cancelado", reservasBloqueio: [] });
      if (!r.ok) return comoResultado(r);
      for (const id of evento.reservasBloqueio) await removerBloqueio(id);
      await recarregar();
      return { ok: true };
    },
    [removerBloqueio, recarregar]
  );

  /** Sorteia a chave com os times confirmados e fecha as inscrições. */
  const sortearChave = useCallback(
    async (evento: Evento, inscricoes: InscricaoEvento[], aleatorio?: () => number): Promise<Resultado> => {
      const confirmados = inscricoes.filter((i) => i.confirmada).map((i) => i.id);
      let partidas: PartidaEvento[];
      try {
        partidas = gerarChave(evento.id, embaralhar(confirmados, aleatorio));
      } catch (err) {
        return { ok: false, erro: traduzirErroEvento(err) };
      }
      const gravacao = await salvarPartidas(partidas);
      if (!gravacao.ok) return comoResultado(gravacao);
      const r = await salvarEvento({ ...evento, status: "chave_sorteada" });
      if (r.ok) await recarregar();
      return comoResultado(r);
    },
    [recarregar]
  );

  /** Lança ou desfaz um resultado; com a final decidida, encerra o evento. */
  const alterarResultado = useCallback(
    async (
      evento: Evento,
      partidas: PartidaEvento[],
      partidaId: string,
      entrada: EntradaResultado | "desfazer"
    ): Promise<{ ok: true; partidas: PartidaEvento[] } | { ok: false; erro: string }> => {
      let depois: PartidaEvento[];
      try {
        depois =
          entrada === "desfazer"
            ? desfazerResultado(partidas, partidaId)
            : registrarResultado(partidas, partidaId, entrada);
      } catch (err) {
        return { ok: false, erro: traduzirErroEvento(err) };
      }
      const gravacao = await salvarPartidas(partidasAlteradas(partidas, depois));
      if (!gravacao.ok) return { ok: false, erro: gravacao.erro };

      const novoStatus = campeao(depois) ? "encerrado" : "chave_sorteada";
      if (novoStatus !== evento.status) {
        await salvarEvento({ ...evento, status: novoStatus });
        await recarregar();
      }
      return { ok: true, partidas: depois };
    },
    [recarregar]
  );

  return {
    eventos,
    carregando,
    recarregar,
    salvarRascunho,
    publicar,
    cancelar,
    sortearChave,
    alterarResultado,
    listarInscricoes,
    listarPartidas,
    confirmarInscricao: async (id: string, confirmada: boolean) => comoResultado(await confirmarInscricao(id, confirmada)),
    removerInscricao: async (id: string) => comoResultado(await removerInscricao(id)),
  };
}

// ─── Página pública do evento ─────────────────────────────────────────────────

export function useEventoPublico(eventoId: string) {
  const { user } = useUserAuth();
  const [evento, setEvento] = useState<Evento | null>(null);
  const [times, setTimes] = useState<InscricaoEvento[]>([]);
  const [minhas, setMinhas] = useState<InscricaoEvento[]>([]);
  const [partidas, setPartidas] = useState<PartidaEvento[]>([]);
  const [carregando, setCarregando] = useState(true);

  const buscar = useCallback(
    () =>
      Promise.all([listarEventos(), listarTimesPublicos(eventoId), listarInscricoes(eventoId), listarPartidas(eventoId)]),
    [eventoId]
  );

  const aplicar = useCallback(
    ([todos, publicos, proprias, chave]: Awaited<ReturnType<typeof buscar>>) => {
      setEvento(todos.find((e) => e.id === eventoId) ?? null);
      setTimes(publicos);
      setMinhas(proprias);
      setPartidas(chave);
      setCarregando(false);
    },
    [eventoId]
  );

  const recarregar = useCallback(async () => aplicar(await buscar()), [aplicar, buscar]);

  useEffect(() => {
    let ativo = true;
    void buscar().then((dados) => {
      if (ativo) aplicar(dados);
    });
    return () => {
      ativo = false;
    };
  }, [buscar, aplicar]);

  const minhaInscricao = useMemo(
    () => (user ? minhas.find((i) => i.usuarioId === user.id) ?? null : null),
    [minhas, user]
  );

  // O total de inscritos não é público; a tela usa os confirmados e o banco decide as vagas.
  const situacao = useMemo(
    () => (evento ? situacaoInscricao(evento, times.length, getHoje()) : null),
    [evento, times.length]
  );

  const inscrever = useCallback(
    async (nomeTime: string): Promise<Resultado> => {
      if (!user) return { ok: false, erro: traduzirErroEvento({ message: "conta_necessaria" }) };
      const erroNome = validarNomeTime(nomeTime);
      if (erroNome) return { ok: false, erro: erroNome };
      const r = await inscreverTime({
        id: gerarId("ins"),
        eventoId,
        usuarioId: user.id,
        nomeTime,
        responsavelNome: user.nome,
        responsavelWhatsapp: user.telefone.replace(/\D/g, ""),
      });
      if (r.ok) await recarregar();
      return comoResultado(r);
    },
    [user, eventoId, recarregar]
  );

  const desistir = useCallback(async (): Promise<Resultado> => {
    if (!minhaInscricao) return { ok: true };
    const r = await removerInscricao(minhaInscricao.id);
    if (r.ok) await recarregar();
    return comoResultado(r);
  }, [minhaInscricao, recarregar]);

  return { evento, times, partidas, minhaInscricao, situacao, carregando, logado: Boolean(user), inscrever, desistir };
}

// ─── Landing ──────────────────────────────────────────────────────────────────

export function useEventosLanding() {
  const [eventos, setEventos] = useState<Evento[]>([]);
  const [nomeCampeao, setNomeCampeao] = useState<string | null>(null);
  const [carregando, setCarregando] = useState(true);

  useEffect(() => {
    let ativo = true;
    void (async () => {
      const lista = await listarEventos();
      const { ultimoEncerrado } = eventosParaLanding(lista, getHoje());
      let nome: string | null = null;
      if (ultimoEncerrado) {
        const [chave, times] = await Promise.all([
          listarPartidas(ultimoEncerrado.id),
          listarTimesPublicos(ultimoEncerrado.id),
        ]);
        const idCampeao = campeao(chave);
        nome = times.find((t) => t.id === idCampeao)?.nomeTime ?? null;
      }
      if (ativo) {
        setEventos(lista);
        setNomeCampeao(nome);
        setCarregando(false);
      }
    })();
    return () => {
      ativo = false;
    };
  }, []);

  return { ...eventosParaLanding(eventos, getHoje()), nomeCampeao, carregando };
}

import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen, fireEvent, waitFor } from "@testing-library/react";
import type { Evento, InscricaoEvento } from "@/lib/eventos/types";

// Spec: SPEC/2026-11-27-eventos-e-torneios.md

const { acoes, toastErro, toastOk } = vi.hoisted(() => ({
  acoes: {} as Record<string, unknown>,
  toastErro: vi.fn(),
  toastOk: vi.fn(),
}));

vi.mock("sonner", () => ({ toast: { error: toastErro, success: toastOk } }));
vi.mock("@/hooks/useEventosService", () => ({ useEventosAdmin: () => acoes }));
vi.mock("@/lib/supabase/institucionalRepository", () => ({ uploadImagemInstitucional: vi.fn() }));

import { AdminEventosPage } from "@/components/admin/AdminEventosPage";

const evento = (parcial: Partial<Evento> = {}): Evento => ({
  id: "ev1", tipo: "torneio", nome: "Copa Reservei", data: "2026-12-05", horaInicio: "18:00", horaFim: "22:00",
  quadraId: "q1", valorInscricao: 100, maxTimes: 4, status: "rascunho", reservasBloqueio: [], ...parcial,
});
const inscricao = (id: string, confirmada: boolean): InscricaoEvento => ({
  id, eventoId: "ev1", nomeTime: `Time ${id}`, responsavelNome: "Ana", responsavelWhatsapp: "91999998888", confirmada,
});

function montar(eventos: Evento[], inscricoes: InscricaoEvento[] = []) {
  Object.assign(acoes, {
    eventos,
    carregando: false,
    salvarRascunho: vi.fn().mockResolvedValue({ ok: true }),
    publicar: vi.fn().mockResolvedValue({ ok: true }),
    cancelar: vi.fn().mockResolvedValue({ ok: true }),
    sortearChave: vi.fn().mockResolvedValue({ ok: true }),
    alterarResultado: vi.fn(),
    listarInscricoes: vi.fn().mockResolvedValue(inscricoes),
    listarPartidas: vi.fn().mockResolvedValue([]),
    confirmarInscricao: vi.fn().mockResolvedValue({ ok: true }),
    removerInscricao: vi.fn().mockResolvedValue({ ok: true }),
  });
  render(<AdminEventosPage />);
}

describe("AdminEventosPage", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    vi.spyOn(window, "confirm").mockReturnValue(true);
  });

  it("cria um rascunho pelo formulário", async () => {
    montar([]);
    fireEvent.click(screen.getByText("Novo evento"));
    fireEvent.change(screen.getByLabelText("Nome"), { target: { value: "Copa de Verão" } });
    fireEvent.change(screen.getByLabelText("Data"), { target: { value: "2026-12-20" } });
    fireEvent.click(screen.getByText("Salvar rascunho"));
    await waitFor(() =>
      expect(acoes.salvarRascunho).toHaveBeenCalledWith(
        expect.objectContaining({ nome: "Copa de Verão", data: "2026-12-20", tipo: "torneio", maxTimes: 8 })
      )
    );
  });

  it("erro de validação aparece no formulário", async () => {
    montar([]);
    (acoes.salvarRascunho as ReturnType<typeof vi.fn>).mockResolvedValue({ ok: false, erro: "Informe um nome com 3 a 80 caracteres." });
    fireEvent.click(screen.getByText("Novo evento"));
    fireEvent.click(screen.getByText("Salvar rascunho"));
    expect(await screen.findByRole("alert")).toHaveTextContent("Informe um nome");
  });

  it("publicar um rascunho e avisar se a quadra estiver ocupada", async () => {
    montar([evento()]);
    (acoes.publicar as ReturnType<typeof vi.fn>).mockResolvedValue({ ok: false, erro: "Já existe reserva na quadra nesse horário." });
    fireEvent.click(screen.getByText("Copa Reservei"));
    fireEvent.click(await screen.findByText("Publicar"));
    await waitFor(() => expect(toastErro).toHaveBeenCalledWith("Não foi possível concluir", { description: "Já existe reserva na quadra nesse horário." }));
  });

  it("sorteio só habilita com 2 confirmados; confirmar pagamento chama o admin", async () => {
    montar([evento({ status: "publicado" })], [inscricao("a", true), inscricao("b", false)]);
    fireEvent.click(screen.getByText("Copa Reservei"));
    const sortear = await screen.findByText("Sortear chave (1 times)");
    expect(sortear).toBeDisabled();

    fireEvent.click(screen.getByText("Confirmar pagamento (Time b)"));
    await waitFor(() => expect(acoes.confirmarInscricao).toHaveBeenCalledWith("b", true));
  });

  it("sortear com 2 confirmados", async () => {
    const inscricoes = [inscricao("a", true), inscricao("b", true)];
    montar([evento({ status: "publicado" })], inscricoes);
    fireEvent.click(screen.getByText("Copa Reservei"));
    fireEvent.click(await screen.findByText("Sortear chave (2 times)"));
    await waitFor(() => expect(acoes.sortearChave).toHaveBeenCalledWith(expect.objectContaining({ id: "ev1" }), inscricoes));
  });

  it("cancelar evento publicado pede confirmação e chama o admin", async () => {
    montar([evento({ status: "publicado" })]);
    fireEvent.click(screen.getByText("Copa Reservei"));
    fireEvent.click(await screen.findByText("Cancelar evento"));
    await waitFor(() => expect(acoes.cancelar).toHaveBeenCalled());
    expect(toastOk).toHaveBeenCalledWith("Evento cancelado.");
  });
});

