"""Divide a transcrição do Claude Code por dia (horário de Brasília), oculta dados
pessoais e remove imagens. Uso: python dividir.py <transcricao.jsonl> <pasta-saida> <dias...>
Dias no formato AAAA-MM-DD. Imprime, por dia, a faixa de horário e os tokens."""

import collections
import datetime as dt
import json
import os
import re
import sys

TZ = dt.timezone(dt.timedelta(hours=-3))

SUBSTITUICOES = [
    (re.compile(r"<email-do-alexsandro>@gmail\.com", re.I), "<email-do-alexsandro>"),
    (re.compile(r"<email-do-jonathan>@gmail\.com", re.I), "<email-do-jonathan>"),
    (re.compile(r"[A-Za-z0-9._%+-]+@gmail\.com", re.I), "<email-removido>"),
    (re.compile(r"eyJhbGciOi[A-Za-z0-9_.\-]{20,}"), "<chave-removida>"),
    (re.compile(r"\b[a-z0-9]{20}\.supabase\.co"), "<projeto>.supabase.co"),
    (re.compile(r"ghp_[A-Za-z0-9]{20,}"), "<token-removido>"),
    (re.compile(r"github_pat_[A-Za-z0-9_]{20,}"), "<token-removido>"),
    (re.compile(r"sb_secret_[A-Za-z0-9_\-]{8,}"), "<chave-removida>"),
    (re.compile(r"sk-ant-[A-Za-z0-9_\-]{20,}"), "<chave-removida>"),
    (re.compile(r"filme[\s_\-]*certo", re.I), "outro-projeto"),
    (re.compile(r"(?:[Cc]:|/c)(?:/|\\\\|\\)Users(?:/|\\\\|\\)alexs", re.I), "<home>"),
]


def limpar_texto(texto):
    for padrao, troca in SUBSTITUICOES:
        texto = padrao.sub(troca, texto)
    return texto


def limpar(obj):
    """Percorre o JSON: troca imagens por um aviso e limpa todo texto."""
    if isinstance(obj, dict):
        if obj.get("type") == "image" and isinstance(obj.get("source"), dict):
            return {"type": "text", "text": "<imagem removida>"}
        return {k: limpar(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return [limpar(v) for v in obj]
    if isinstance(obj, str):
        return limpar_texto(obj)
    return obj


def main():
    origem, pasta, *dias = sys.argv[1:]
    saidas = {d: [] for d in dias}
    faixa, tokens, vistos = {}, collections.defaultdict(collections.Counter), set()
    dia_atual = None
    for linha in open(origem, encoding="utf-8"):
        try:
            e = json.loads(linha)
        except json.JSONDecodeError:
            continue
        ts = e.get("timestamp")
        if ts:
            t = dt.datetime.fromisoformat(ts.replace("Z", "+00:00")).astimezone(TZ)
            dia_atual = t.strftime("%Y-%m-%d")
            if dia_atual in saidas:
                f = faixa.setdefault(dia_atual, [t, t])
                f[0], f[1] = min(f[0], t), max(f[1], t)
        if dia_atual not in saidas:
            continue
        m = e.get("message") if isinstance(e.get("message"), dict) else {}
        u = m.get("usage")
        if e.get("type") == "assistant" and u and (m.get("id"), e.get("requestId")) not in vistos:
            vistos.add((m.get("id"), e.get("requestId")))
            c = tokens[dia_atual]
            c["entrada"] += u.get("input_tokens", 0)
            c["saida"] += u.get("output_tokens", 0)
            c["leitura_cache"] += u.get("cache_read_input_tokens", 0)
            c["escrita_cache"] += u.get("cache_creation_input_tokens", 0)
        saidas[dia_atual].append(json.dumps(limpar(e), ensure_ascii=False))

    for d in dias:
        if not saidas[d]:
            continue
        ini = faixa[d][0]
        nome = os.path.join(pasta, f"{d}-{ini:%H%M}-claude-code-alexsandro.jsonl")
        with open(nome, "w", encoding="utf-8", newline="\n") as arq:
            arq.write("\n".join(saidas[d]) + "\n")
        c = tokens[d]
        print(json.dumps({"dia": d, "arquivo": os.path.basename(nome), "inicio": f"{faixa[d][0]:%H:%M}",
                          "fim": f"{faixa[d][1]:%H:%M}", "linhas": len(saidas[d]), **c}))


if __name__ == "__main__":
    main()

